/** Resolusi slug → layanan v3 (dipakai catch-all /layanan/[...slug]). */
export function resolveKatalogV3(slug: string): KatalogV3Service | undefined {
  return V3_MAP.get(slug);
}

/** Semua slug v3 — dipakai generateStaticParams + sitemap. */
export const KATALOG_V3_SLUGS: string[] = KATALOG_V3.map((s) => s.slug);

const V3_MAP = new Map(KATALOG_V3.map((s) => [s.slug, s]));

/** Layanan satu kategori v3 (untuk related/internal linking). */
export function katalogV3ByCategory(code: string): KatalogV3Service[] {
  return KATALOG_V3.filter((s) => s.categoryCode === code);
}

